.conversations-dialog-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--gh-overlay-bg, rgba(0,0,0,0.5));
  z-index: 1000003;
  display: flex;
  align-items: center;
  justify-content: center;
}
.conversations-dialog {
  background: var(--gh-bg, white);
  border-radius: 12px;
  padding: 20px;
  min-width: 320px;
  max-width: min(480px, calc(100vw - 40px));
  box-shadow: var(--gh-shadow-lg, 0 10px 40px rgba(0,0,0,0.2));
}
/* 弹窗 portal 到宿主页面，宿主（如 ChatGPT 新版）对 input 全局 appearance:none
   会把原生勾选框剥成透明盒子；这里恢复原生渲染 */
.conversations-dialog-overlay input[type="checkbox"] {
  appearance: auto;
}
.conversations-dialog-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--gh-text, #1f2937);
  margin-bottom: 16px;
}
.conversations-dialog-message {
  font-size: 14px;
  color: var(--gh-text-secondary, #4b5563);
  margin-bottom: 20px;
  line-height: 1.5;
  white-space: pre-line;
  word-break: break-word;
  overflow-wrap: break-word;
}
.conversations-dialog-section {
  margin-bottom: 16px;
}
.conversations-dialog-section label {
  display: block;
  font-size: 13px;
  color: var(--gh-text-secondary, #6b7280);
  margin-bottom: 8px;
}
.conversations-dialog-input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--gh-input-border, #d1d5db);
  border-radius: 8px;
  font-size: 14px;
  box-sizing: border-box;
  background: var(--gh-input-bg, #ffffff);
  color: var(--gh-text, #1f2937);
}
.conversations-dialog-input:focus {
  outline: none;
  border-color: var(--gh-input-focus-border, #4285f4);
  box-shadow: var(--gh-input-focus-shadow, 0 0 0 2px rgba(66,133,244,0.1));
}
.conversations-dialog-buttons {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 20px;
}
.emoji-grid-hidden-scrollbar::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}
@keyframes gh-highlight-fade {
  0% { background-color: var(--gh-highlight-pulse, rgba(59, 130, 246, 0.3)); }
  100% { background-color: transparent; }
}
.conversations-folder-select-highlight {
  animation: gh-highlight-fade 2s ease-out;
}
.conversations-batch-tag-list {
  max-height: 240px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 12px;
}
.conversations-batch-tag-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 13px;
  color: var(--gh-text, #1f2937);
}
.conversations-batch-tag-item:hover {
  background: var(--gh-hover, #f3f4f6);
}
.conversations-batch-tag-item .conversations-batch-tag-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.conversations-batch-tag-dot {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  flex-shrink: 0;
}
/* 标签管理：行与图标按钮的状态。弹窗渲染在宿主页面，只能用 ThemeManager 写在 html 上的预置变量；
   已选与编辑中都用主色淡底（编辑中更深一档），不用警告色，否则深色主题下会冒出浅色块 */
.conversations-tag-manager-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid var(--gh-border, #e5e7eb);
  transition: background-color 0.15s;
}
.conversations-tag-manager-row:hover {
  background: var(--gh-hover, #f3f4f6);
}
.conversations-tag-manager-row.is-selected {
  background: color-mix(in srgb, var(--gh-primary, #4285f4) 8%, transparent);
}
.conversations-tag-manager-row.is-editing {
  background: color-mix(in srgb, var(--gh-primary, #4285f4) 14%, transparent);
}
.conversations-tag-manager-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--gh-text-tertiary, #9ca3af);
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s;
}
.conversations-tag-manager-icon-btn:hover {
  background: var(--gh-hover, #f3f4f6);
  color: var(--gh-text, #1f2937);
}
.conversations-tag-manager-icon-btn.is-active {
  background: color-mix(in srgb, var(--gh-primary, #4285f4) 16%, transparent);
  color: var(--gh-primary-text, var(--gh-primary, #4285f4));
}
.conversations-tag-manager-icon-btn.danger:hover {
  background: var(--gh-bg-danger, #fef2f2);
  color: var(--gh-text-danger, #ef4444);
}

