}

.gh-export-footer-actions .gh-dialog-btn-primary:disabled {
  box-shadow: none;
}

/* 分段导出的唯一入口：主色淡底 + 主色描边 + 主色字，比“取消”醒目，又不和实心的“导出”抢 */
.gh-export-segmented-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 36px;
  padding: 7px 12px;
  font: inherit;
  font-size: 13px;
  font-weight: 550;
  line-height: 1.25;
  white-space: nowrap;
  flex-shrink: 0;
