/* 弹窗骨架（头部 / 内容 / 页脚、背景、圆角、阴影）来自共享的 .gh-dialog-frame，这里只放编辑器自己的部分 */
.gh-chain-editor {
  color: var(--gh-text, #1f2937);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  animation: slideUp 0.25s ease-out;
}

