  font-weight: 400;
  line-height: 1.45;
}

/* 内容区的滚动条样式（滚动与内边距来自共享的 .gh-dialog-frame-body） */
.gh-chain-editor-scroll {
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--gh-text-tertiary, #8d94a1) 64%, transparent)
    transparent;
}

.gh-chain-editor-scroll::-webkit-scrollbar {
  width: 10px;
}

.gh-chain-editor-scroll::-webkit-scrollbar-track {
  background: transparent;
}

.gh-chain-editor-scroll::-webkit-scrollbar-thumb {
  min-height: 42px;
  border: 3px solid transparent;
  border-radius: 999px;
  background: color-mix(in srgb, var(--gh-text-tertiary, #8d94a1) 56%, transparent);
  background-clip: content-box;
}

.gh-chain-editor-scroll::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--gh-text-secondary, #6b7280) 72%, transparent);
  background-clip: content-box;
}

.gh-chain-form-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 12px;
}

.gh-chain-field {
  display: flex;
