  font-size: 13px;
  font-weight: 600;
}

.gh-chain-field input,
.gh-chain-field textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid var(--gh-input-border, #d1d5db);
  border-radius: 6px;
  background: var(--gh-input-bg, var(--gh-bg, #ffffff));
  color: var(--gh-text, #1f2937);
  font: inherit;
  font-size: 13px;
  outline: none;
}

.gh-chain-field input {
  height: 34px;
  padding: 0 10px;
}

.gh-chain-field textarea {
  min-height: 74px;
  padding: 8px 10px;
  resize: vertical;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  line-height: 1.45;
}

.gh-chain-field input:focus,
.gh-chain-field textarea:focus {
  border-color: var(--gh-primary, #4285f4);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--gh-primary, #4285f4) 12%, transparent);
}

.gh-chain-visibility-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: 100%;
  padding: 5px 8px 5px 6px;
  border: 1px solid var(--gh-border, #e5e7eb);
  border-radius: 999px;
  background: var(--gh-bg-secondary, #f9fafb);
  color: var(--gh-text, #374151);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}

.gh-chain-visibility-toggle input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.gh-chain-visibility-switch {
  position: relative;
  width: 28px;
  height: 16px;
  flex: 0 0 28px;
  border-radius: 999px;
  background: var(--gh-border, #d1d5db);
