  gap: 12px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--gh-border, #e5e7eb);
}
.gh-style-editor-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: var(--gh-text, #1f2937);
}
.gh-style-editor-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
