  background: var(--gh-bg-secondary, #f9fafb);
  color: var(--gh-text, #374151);
  font-size: 13px;
  cursor: pointer;
}
/* 宿主页（如 ChatGPT）可能对 input 全局 appearance:none，这里恢复原生单选框 */
.gh-style-editor-mode input {
  margin: 0;
